    data = sys.stdin.read().split()
    q = int(data[0])
    L, pos, out = [], {}, []
    p = 1
    for _ in range(q):
        op = data[p]; v = int(data[p + 1]); p += 2
        if op == 'insert':
            if v in pos:
                out.append(0)
            else:
                pos[v] = len(L)
                L.append(v)
                out.append(1)
        elif op == 'remove':
            if v not in pos:
                out.append(0)
            else:
                i = pos.pop(v)
                last = L.pop()
                if last != v:
                    L[i] = last
                    pos[last] = i
                out.append(1)
        elif op == 'search':
            out.append(1 if v in pos else 0)
        else:
            out.append(L[v % len(L)] if L else -1)
    print('\n'.join(map(str, out)))

main()

